using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class NativeOutputWindowsProof {
 class Memory:IScreenHookMemory,ICapacityKeyMemory {
  public Dictionary<int,byte> Bytes=new Dictionary<int,byte>();public void Load(ushort seg,byte[] b){if(b.Length!=65536)throw new Exception("Length");for(int i=0;i<65536;i++){int p=(seg<<4)+i;byte old;if(Bytes.TryGetValue(p,out old)&&old!=b[i])throw new Exception("Physical alias mismatch");Bytes[p]=b[i];}}
  public ushort ReadWord(ushort s,ushort o){byte a,b;if(!Bytes.TryGetValue((s<<4)+o,out a)||!Bytes.TryGetValue((s<<4)+(ushort)(o+1),out b))throw new Exception("Uncaptured word read");return (ushort)(a|b<<8);}
  public void WriteWord(ushort s,ushort o,ushort v){int p=(s<<4)+o,q=(s<<4)+(ushort)(o+1);if(!Bytes.ContainsKey(p)||!Bytes.ContainsKey(q))throw new Exception("Uncaptured word write");Bytes[p]=(byte)v;Bytes[q]=(byte)(v>>8);}
  public byte ReadByte(ushort s,ushort o){return Bytes[(s<<4)+o];}
  public void WriteByte(ushort s,ushort o,byte v){int p=(s<<4)+o;if(!Bytes.ContainsKey(p))throw new Exception("Uncaptured byte write");Bytes[p]=v;}
  public void OrByte(ushort s,ushort o,byte b){throw new Exception("Video effect");}
  public void Compare(ushort seg,byte[] b){if(b.Length!=65536)throw new Exception("Length");for(int i=0;i<65536;i++)if(Bytes[(seg<<4)+i]!=b[i])throw new Exception("Segment "+seg.ToString("X4")+" byte "+i.ToString("X4"));}
 }
 static ushort H(string s){return Convert.ToUInt16(s,16);}static SignedDivide16State Parse(string[] a,int i){return new SignedDivide16State{AX=H(a[i]),BX=H(a[i+1]),CX=H(a[i+2]),DX=H(a[i+3]),SI=H(a[i+4]),DI=H(a[i+5]),BP=H(a[i+6]),CS=H(a[i+7]),IP=H(a[i+8]),DS=H(a[i+9]),ES=H(a[i+10]),SS=H(a[i+11]),SP=H(a[i+12]),EFlags=Convert.ToUInt32(a[i+13],16)};}
 static string Show(SignedDivide16State s){return s.AX+":"+s.BX+":"+s.CX+":"+s.DX+":"+s.SI+":"+s.DI+":"+s.BP+":"+s.CS+":"+s.IP+":"+s.DS+":"+s.ES+":"+s.SS+":"+s.SP+":"+s.EFlags;}

 static SignedDivide16State State(string d,string n){return Parse(File.ReadAllText(Path.Combine(d,n+"-state.txt")).Split((char[])null,StringSplitOptions.RemoveEmptyEntries),0);}
 static void Check(Memory m,string d,string n,SignedDivide16State s){if(Show(s)!=Show(State(d,n)))throw new Exception(n+" CPU: "+Show(s)+" expected "+Show(State(d,n)));m.Compare(s.DS,File.ReadAllBytes(Path.Combine(d,n+"-ds.bin")));m.Compare(s.SS,File.ReadAllBytes(Path.Combine(d,n+"-ss.bin")));}


 static void Add(Memory m,int address,byte[] b){for(int i=0;i<b.Length;i++){byte old;if(m.Bytes.TryGetValue(address+i,out old)&&old!=b[i])throw new Exception("Metadata alias");m.Bytes[address+i]=b[i];}}
 static void Bda(Memory m,string d,string n){byte[] b=File.ReadAllBytes(Path.Combine(d,n+"-bda.bin"));for(int i=0;i<256;i++)if(m.Bytes[0x400+i]!=b[i])throw new Exception(n+" BDA "+i.ToString("X2"));}
 static void Plane(Mode12Plane2Surface video,string d,string n){byte[] b=File.ReadAllBytes(Path.Combine(d,n+"-plane2.bin"));for(int i=0;i<65536;i++)if(video.Bytes[i]!=b[i])throw new Exception(n+" plane2 "+i.ToString("X4"));}
 class Pair:IMode12Surface {public Mode12Plane2Surface Plane;public Mode12CellSurface Cells=new Mode12CellSurface();public void WriteGlyph(int r,int c,byte ch,byte color){Plane.WriteGlyph(r,c,ch,color);Cells.WriteGlyph(r,c,ch,color);}public void Scroll(int t,int l,int b,int right,int lines,byte color){Plane.Scroll(t,l,b,right,lines,color);Cells.Scroll(t,l,b,right,lines,color);}}
 class Keyboard:ICapacityInterruptEffects {
  public string Dir;public int Count;public Mode12Plane2Surface Video;
  public SignedDivide16State Interrupt(byte number,IHorizontalRasterMemory memory,SignedDivide16State s){if(number!=0x16)throw new Exception("Unexpected external interrupt");string n="key-"+Count;Memory m=(Memory)memory;Check(m,Dir,n+"-entry",s);Bda(m,Dir,n+"-entry");Plane(Video,Dir,n+"-entry");var after=State(Dir,n+"-returned");Memory captured=new Memory();captured.Load(after.DS,File.ReadAllBytes(Path.Combine(Dir,n+"-returned-ds.bin")));captured.Load(after.SS,File.ReadAllBytes(Path.Combine(Dir,n+"-returned-ss.bin")));foreach(var b in captured.Bytes)m.Bytes[b.Key]=b.Value;byte[] bda=File.ReadAllBytes(Path.Combine(Dir,n+"-returned-bda.bin"));for(int i=0;i<256;i++)m.Bytes[0x400+i]=bda[i];Plane(Video,Dir,n+"-returned");Count++;return after;}
 }
 static int Main(string[] args){try{for(int mode=2;mode<3;mode++){string d=args[0];string start=mode==2?"comparison":"entry";var s=State(d,start);Memory m=new Memory();m.Load(s.DS,File.ReadAllBytes(Path.Combine(d,start+"-ds.bin")));m.Load(s.SS,File.ReadAllBytes(Path.Combine(d,start+"-ss.bin")));Add(m,0x400,File.ReadAllBytes(Path.Combine(d,"entry-bda.bin")));Add(m,0x40,File.ReadAllBytes(Path.Combine(d,"interrupt-vector.bin")));Add(m,0x1f1e0+0x1cc,File.ReadAllBytes(Path.Combine(d,"saved-vector.bin")));var plane=new Mode12Plane2Surface(File.ReadAllBytes(Path.Combine(d,"entry-plane2.bin")),new ExternalVgaFont(File.ReadAllBytes(Path.Combine(d,"analysis-only-font.bin"))));if(mode==2){byte[] header=File.ReadAllBytes(Path.Combine(d,"measured-count.bin"));Add(m,s.ES<<4,header);}var keyboard=new Keyboard{Dir=d,Video=plane};var pair=new Pair{Plane=plane};var bios=new Mode12BiosTransfer(new Mode12VideoServices(pair),0xf000,0xcea4);var interrupts=new ScreenHookInterruptEffects(bios,keyboard,0x1f1e,0x235,0x871e);var effects=CapacityMessageNativeEffects.CreateWithNativeCharacters(interrupts,0x1f1e,0x1f1e);SignedDivide16State final;string n;if(mode==2){var result=BufferedPointCaller.ExecuteCapacityAtComparisonThroughReturn(m,effects,s,0x1f1e,0x1dbb);if(result.Outcome!=BufferedPointOutcome.Completed||!result.RetfExecuted)throw new Exception("Caller outcome");final=result.State;n="caller-returned";}else{var result=mode==0?CapacityMessageHandler.Execute(m,effects,s,0x1f1e,0x1dbb):CapacityMessageHandler.ExecuteThroughReturn(m,effects,s,0x1f1e,0x1dbb);if(result.Outcome!=CapacityMessageOutcome.ReachedReturn||result.RetfExecuted!=(mode==1))throw new Exception("Handler outcome");final=result.State;n=mode==0?"before-return":"returned";}if(keyboard.Count!=3)throw new Exception("Keyboard count");Check(m,d,n,final);Bda(m,d,n);Plane(plane,d,n);foreach(int width in new[]{3840,7680}){int height=width*9/16;using(var bitmap=new System.Drawing.Bitmap(width,height))using(var g=System.Drawing.Graphics.FromImage(bitmap))using(var font=new System.Drawing.Font("Consolas",height/30f*.8f,System.Drawing.GraphicsUnit.Pixel)){g.Clear(System.Drawing.Color.FromArgb(176,176,176));ScoreModern.NativeInterfaceText.DrawSurface(g,pair.Cells,System.Drawing.PointF.Empty,width/80f,height/30f,font,System.Drawing.Brushes.Black,null,30);bitmap.Save(Path.Combine(args[1],"native-output-overlay-"+width+".png"),System.Drawing.Imaging.ImageFormat.Png);}}Console.WriteLine("PASS complete native capacity output mode "+mode+": full CPU/DS/SS/BDA/65536 plane2 bytes; only three keyboard effects external.");}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}} }
